import { atom, read, update } from 'claude-code'
import type { EngineInterface } from 'claude-code'

import type { FileFacts } from '../../types'
import { cacheOf, fetchChanged, isGone, readRunFiles } from './home'
import type { FileCache } from './home'
import { inferFacts } from './infer'
import { locate, sessionFile } from './session'
import type { SessionFile } from './session'
import { refresh } from './view'

const filesState = atom({ plugin: 'spindle', key: 'files' } as const, null)
const viewState = atom({ plugin: 'spindle', key: 'view' } as const, null)

export const POLL_MS = 2000

async function readSession($: EngineInterface, where: SessionFile, hasHome: boolean, cache: FileCache) {
  if (!hasHome) {
    try {
      const text = await $.fs.read(where.path)
      return { text: typeof text === 'string' ? text : null, cache: {} }
    } catch {
      return { text: null, cache: {} }
    }
  }
  try {
    const stat = await $.fs.stat(where.path)
    const fetched = await fetchChanged($, [{ path: where.path, mtimeMs: stat.mtimeMs }], cache)
    const file = fetched[0]?.text
    return { text: file?.kind === 'text' ? file.text : null, cache: cacheOf(fetched) }
  } catch {
    return { text: null, cache: {} }
  }
}

async function readFacts($: EngineInterface, cache: FileCache): Promise<{ facts: FileFacts | null; cache: FileCache }> {
  const where = await sessionFile($)
  if (where === null) return { facts: null, cache: {} }
  const known = await read($, filesState)
  const session = await readSession($, where, known?.home != null, cache)
  const location = locate(session.text, where.mitosis)
  if (location === null) return { facts: null, cache: session.cache }
  if (location.home !== null && (await isGone($, location.home))) return { facts: null, cache: session.cache }
  const run = await readRunFiles($, location, cache)
  return { facts: inferFacts(run.files), cache: { ...session.cache, ...run.cache } }
}

export async function startPolling($: EngineInterface): Promise<void> {
  let polling: { cache: FileCache; isBusy: boolean } = { cache: {}, isBusy: false }
  const pass = async () => {
    if (polling.isBusy) return
    const shown = await read($, viewState)
    if (shown?.isFinished === true) return
    polling = { ...polling, isBusy: true }
    try {
      const { facts, cache } = await readFacts($, polling.cache)
      polling = { ...polling, cache }
      const previous = await read($, filesState)
      if (JSON.stringify(previous) !== JSON.stringify(facts)) await update($, filesState, () => facts)
      await refresh($)
    } finally {
      polling = { ...polling, isBusy: false }
    }
  }
  await pass()
  $.clock.every(POLL_MS, () => {
    void pass()
  })
}

files.hooks/run/signals.ts:
import { atom, read, update } from 'claude-code'
import type { Hook } from 'claude-code'

import type { AgentRow, Lane, Role, Signals, Stage } from '../../types'
import { isPipelineClean, isRunScript, isShipping, simpleCommands } from './command'
import { contextMax, contextTokens, stepCost } from './cost'
import { STAGES, isRunStarted } from './infer'
import { NO_SIGNALS } from './state'
import { refresh } from './view'
import type { ViewDollar } from './view'

const MAX_AGENTS = 200

const signalsState = atom({ plugin: 'spindle', key: 'signals' } as const, NO_SIGNALS)
const filesState = atom({ plugin: 'spindle', key: 'files' } as const, null)

type CallSignal = {
  stage: Stage | null
  lane: Lane | null
  isPullRequest: boolean
  isClean: boolean
  isRunEntry: boolean
}

const NO_CALL: CallSignal = { stage: null, lane: null, isPullRequest: false, isClean: false, isRunEntry: false }

const ROLES: readonly (readonly [RegExp, Role])[] = [
  [/^interphase:(scout|spec-reviewer)$/, 'scribe'],
  [/^(?:[^:]+:)?(code-reviewer|security-reviewer|conformance-auditor)$/, 'detective'],
  [/^(?:[^:]+:)?validator$/, 'judge'],
]

export const roleOf = (type: string): Role => ROLES.find(([pattern]) => pattern.test(type))?.[1] ?? 'plain'

const textOf = (value: unknown) => (typeof value === 'string' ? value : '')

function laneOf(args: string): Lane | null {
  const trimmed = args.trim()
  if (trimmed.endsWith('Interview me first.')) return 'full'
  if (trimmed.endsWith('Work autonomously.')) return 'standard'
  return null
}

function bashSignal(text: string): CallSignal {
  const commands = simpleCommands(text) ?? []
  const cleans = commands.filter(isPipelineClean)
  if (cleans.length > 0) return { ...NO_CALL, stage: 'clean', isClean: cleans.some(command => command.decidesStatus) }
  const runs = commands.filter(isRunScript)
  if (runs.length === 0) return NO_CALL
  return { ...NO_CALL, stage: runs.some(isShipping) ? 'ship' : 'build' }
}

function callSignal(tool: string, input: Readonly<Record<string, unknown>>): CallSignal {
  if (tool === 'Skill') {
    const skill = textOf(input.skill)
    if (skill.startsWith('interphase:')) {
      return { ...NO_CALL, stage: 'spec', lane: laneOf(textOf(input.args)), isRunEntry: true }
    }
    if (skill === 'pipeline:run') return { ...NO_CALL, stage: 'spec', isRunEntry: true }
    if (skill === 'lighthouse:test') return { ...NO_CALL, stage: 'integrate' }
    return NO_CALL
  }
  if (tool === 'Bash') return bashSignal(textOf(input.command))
  if (tool.endsWith('create_pull_request')) return { ...NO_CALL, stage: 'ship', isPullRequest: true }
  return NO_CALL
}

const laterStage = (known: Stage | null, reached: Stage | null): Stage | null => {
  if (reached === null) return known
  if (known === null) return reached
  return STAGES.indexOf(reached) > STAGES.indexOf(known) ? reached : known
}

function pullNumber(result: unknown): string | null {
  const text = typeof result === 'string' ? result : (JSON.stringify(result) ?? '')
  return /\/pull\/(\d+)/.exec(text)?.[1] ?? /"number":(\d+)/.exec(text)?.[1] ?? null
}

function exitedClean(ran: { deny?: string; isError?: boolean; result?: unknown }): boolean {
  if (ran.deny !== undefined || ran.isError === true) return false
  const result = ran.result
  const exitCode = typeof result === 'object' && result !== null ? (result as { exitCode?: unknown }).exitCode : undefined
  return exitCode === undefined || exitCode === 0
}

async function change($: ViewDollar, apply: (signals: Signals) => Signals): Promise<void> {
  await update($, signalsState, apply)
  await refresh($)
}

export const toolCallSignals: Hook<'tool.call'> = async ($, e, next) => {
  const input = e as unknown as Readonly<Record<string, unknown>>
  const signal = callSignal(String(e.tool), input)
  if (signal.stage === null) return next(e)
  const at = await $.clock.now()
  const files = signal.isRunEntry ? await read($, filesState) : null
  const afterDone = (signals: Signals): Signals =>
    signal.isRunEntry && signals.isCleanDone
      ? { ...NO_SIGNALS, finishedRun: files === null ? null : { slug: files.slug, home: files.home } }
      : signals
  await change($, current => {
    const signals = afterDone(current)
    return {
      ...signals,
      callStage: laterStage(signals.callStage, signal.stage),
      lane: signals.lane ?? signal.lane,
      firstCallAt: signals.firstCallAt ?? at,
      isPullRequestRunning: signals.isPullRequestRunning || signal.isPullRequest,
    }
  })
  const ran = await next(e).catch(async (error: unknown) => {
    if (signal.isPullRequest) await change($, signals => ({ ...signals, isPullRequestRunning: false }))
    throw error
  })
  if (signal.isClean && exitedClean(ran)) {
    await change($, signals => ({ ...signals, isCleanDone: true }))
  }
  if (signal.isPullRequest) {
    const head = input.head
    const number = ran.deny === undefined ? pullNumber(ran.result) : null
    await change($, signals => ({
      ...signals,
      isPullRequestRunning: false,
      pulls:
        typeof head === 'string' && number !== null
          ? [...signals.pulls.filter(pull => pull.head !== head), { head, number }]
          : signals.pulls,
    }))
  }
  return ran
}

export const agentSpawnSignals: Hook<'agent.spawn'> = async ($, e, next) => {
  const started = await next(e)
  if (started.deny !== undefined) return started
  const at = await $.clock.now()
  const agent: AgentRow = {
    id: started.agentId ?? e.tool_use_id,
    role: roleOf(e.subagentType),
    type: e.subagentType,
    description: e.description,
    prompt: e.prompt,
    model: started.model,
    startedAt: at,
    contextTokens: 0,
    contextMax: contextMax(started.model),
    isRunning: true,
  }
  await change($, signals => ({
    ...signals,
    agents: [...signals.agents.filter(one => one.id !== agent.id), agent].slice(-MAX_AGENTS),
  }))
  return started
}

export const turnStepSignals: Hook<'turn.step'> = async function* ($, e, next) {
  const result = yield* next(e)
  const usage = result.usage
  if (usage === null) return result
  const model = usage.model || e.model
  const [signals, files] = await Promise.all([read($, signalsState), read($, filesState)])
  const isRunKnown = isRunStarted(files, signals)
  const agentId = e.agentId
  await change($, current => ({
    ...current,
    costUsd: isRunKnown ? current.costUsd + stepCost(model, usage) : current.costUsd,
    agents:
      agentId === undefined
        ? current.agents
        : current.agents.map(agent =>
            agent.id === agentId
              ? { ...agent, model, contextTokens: contextTokens(usage), contextMax: contextMax(model) }
              : agent,
          ),
  }))
  return result
}

export const turnCompleteSignals: Hook<'turn.complete'> = async ($, e, next) => {
  const agentId = e.agentId
  if (agentId !== undefined) {
    await change($, signals => ({
      ...signals,
      agents: signals.agents.map(agent => (agent.id === agentId ? { ...agent, isRunning: false, prompt: '' } : agent)),
    }))
  }
  return next(e)
}

