import type { Stage } from '../../types'
import { CRAB_CSS, ROLE_COLOR } from './crew'

export const FONT = "-apple-system,BlinkMacSystemFont,'SF Pro Text','Segoe UI',system-ui,sans-serif"
export const ACCENT = '#8f8cf4'
export const DONE = '#5fbf8f'
export const FAIL = '#D0453F'
export const LANE_COLORS = ['#1D9E75', '#378ADD', '#BA7517', '#7F77DD', '#D85A30'] as const

export type StageInfo = { id: Stage; name: string; color: string }

export const STAGE_TABLE: readonly StageInfo[] = [
  { id: 'spec', name: 'Spec', color: ROLE_COLOR.interphase },
  { id: 'build', name: 'Build', color: ROLE_COLOR.mitosis },
  { id: 'review', name: 'Review', color: ROLE_COLOR.review },
  { id: 'fix', name: 'Fix', color: ROLE_COLOR.verdict },
  { id: 'ship', name: 'Ship', color: ROLE_COLOR.ship },
  { id: 'integrate', name: 'Integrate', color: ROLE_COLOR.ship },
  { id: 'clean', name: 'Clean-up', color: ROLE_COLOR.continuity },
]

export const THEME_CSS = `<style>
.sv-t{fill:#77776f}.sv-s{fill:#85857f}.sv-m{fill:#93938d}.sv-k{fill:rgba(128,128,120,.24)}.sv-tile{fill:rgba(128,128,120,.12)}
.sv-tk{fill:#93938d;opacity:.6}.sv-mstroke{stroke:#93938d}.sv-mfill{fill:#93938d}
.sv-live{animation:sv-p 1.6s ease-in-out infinite}@keyframes sv-p{50%{opacity:.3}}
@media (prefers-reduced-motion: reduce){.sv-live{animation:none}}
</style>`

const ESCAPES: Readonly<Record<string, string>> = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }

export const xml = (value: unknown) => String(value).replace(/[&<>"]/g, ch => ESCAPES[ch] ?? ch)

export const noise = (x: number, y: number) => {
  const s = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453
  return s - Math.floor(s)
}

export const charEm = (ch: string) => (/[\s.,:;'|!il1()[\]]/.test(ch) ? 0.3 : /[A-Z@%mw]/.test(ch) ? 0.72 : 0.56)

export const textWidth = (s: string, size: number) => [...s].reduce((w, ch) => w + charEm(ch) * size, 0)

export const CELL_PX = 8

export const TEXT_PX = 13

export const columnsOf = (s: string) => Math.max([...s].length, Math.ceil(textWidth(s, TEXT_PX) / CELL_PX))

const FIT_SLACK = 0.01

export function fitText(s: string, size: number, maxW: number): string {
  if (textWidth(s, size) <= maxW + FIT_SLACK) return s
  const chars = [...s]
  const kept = chars.findIndex((_, i) => textWidth(chars.slice(0, i + 1).join('') + '…', size) > maxW + FIT_SLACK)
  return chars.slice(0, kept === -1 ? chars.length : kept).join('') + '…'
}

export const stageIndex = (stage: Stage | 'unknown') => STAGE_TABLE.findIndex(one => one.id === stage)

export const stageInfo = (stage: Stage | 'unknown'): StageInfo | null => STAGE_TABLE[stageIndex(stage)] ?? null

export type Mark = 'running' | 'done' | 'failed' | 'pending'

export function statusMark(x: number, y: number, status: Mark, color: string): string {
  if (status === 'running') return `<circle class="sv-live" cx="${x}" cy="${y}" r="3.5" fill="${color}"/>`
  if (status === 'done') {
    return `<path d="M${x - 5} ${y}l3.5 3.5 6.5-7" fill="none" stroke="#3B9C5F" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/>`
  }
  if (status === 'failed') {
    return `<path d="M${x - 4} ${y - 4}l8 8M${x + 4} ${y - 4}l-8 8" stroke="${FAIL}" stroke-width="1.8" stroke-linecap="round"/>`
  }
  return `<circle cx="${x}" cy="${y}" r="5" fill="none" class="sv-mstroke" stroke-width="1.4"/>`
}

export const tip = (lines: readonly string[]) =>
  lines.length === 0 ? '' : `<title>${xml(lines.join('\n'))}</title><rect width="100%" height="100%" fill="transparent"/>`

export const svg = (W: number, H: number, body: string, tipLines: readonly string[] = []) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}">${tip(tipLines)}${THEME_CSS}${CRAB_CSS}${body}</svg>`

export const fluidSvg = (H: number, body: string, tipLines: readonly string[] = []) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="${H}" overflow="hidden">${tip(tipLines)}${THEME_CSS}${body}</svg>`

export const CHIP_H = 16
const CHIP_PX = 10.5
const CHIP_PAD = 12
const SEMIBOLD_WIDTH = 1.08

export const chipWidthOf = (label: string) => Math.ceil(textWidth(label, CHIP_PX) * SEMIBOLD_WIDTH) + CHIP_PAD

export function chipSvg(label: string): string {
  const W = chipWidthOf(label)
  return svg(
    W,
    CHIP_H,
    `<rect class="sv-k" y="1" width="${W}" height="${CHIP_H - 2}" rx="4"/>
<text class="sv-s" x="${W / 2}" y="${CHIP_H / 2 + 3.5}" text-anchor="middle" font-family="${FONT}" font-size="${CHIP_PX}" font-weight="600">${xml(label)}</text>`,
  )
}

files.hooks/run/home.ts:
import type { EngineInterface, FsEntry } from 'claude-code'

import type { RunLocation } from './session'

export type FileText = { kind: 'absent' } | { kind: 'unreadable' } | { kind: 'text'; text: string }

const ABSENT: FileText = { kind: 'absent' }
const UNREADABLE: FileText = { kind: 'unreadable' }

export type CachedText = { mtimeMs: number; text: FileText }
export type FileCache = Readonly<Record<string, CachedText>>

export type ReviewRound = {
  n: number
  names: readonly string[]
  times: Readonly<Record<string, number>>
  verdicts: Readonly<Record<string, FileText>>
  findings: Readonly<Record<string, FileText>>
}

export type RunFiles = {
  location: RunLocation
  homeEntries: readonly FsEntry[] | null
  rounds: readonly ReviewRound[]
  plan: FileText
  planMtimeMs: number | null
  state: FileText
  laneNames: readonly string[]
  ledger: FileText
}

type Wanted = { path: string; mtimeMs: number }
type Fetched = Wanted & { text: FileText }

const ROUND_FOLDER = /^round-(\d+)$/
const VERDICT = /^(.+)\.verdict\.json$/
const FINDINGS = /^(.+)\.findings\.json$/

export async function listing($: EngineInterface, path: string): Promise<readonly FsEntry[] | null> {
  try {
    return await $.fs.list(path)
  } catch {
    return null
  }
}

export async function isGone($: EngineInterface, path: string): Promise<boolean> {
  try {
    return !(await $.fs.exists(path))
  } catch {
    return false
  }
}

async function readText($: EngineInterface, path: string): Promise<FileText> {
  try {
    const text = await $.fs.read(path)
    return typeof text === 'string' ? { kind: 'text', text } : UNREADABLE
  } catch {
    return UNREADABLE
  }
}

export async function fetchChanged($: EngineInterface, wanted: readonly Wanted[], cache: FileCache): Promise<readonly Fetched[]> {
  return Promise.all(
    wanted.map(async ({ path, mtimeMs }) => {
      const known = cache[path]
      if (known !== undefined && known.mtimeMs === mtimeMs && known.text.kind !== 'unreadable') return { path, mtimeMs, text: known.text }
      return { path, mtimeMs, text: await readText($, path) }
    }),
  )
}

export const cacheOf = (fetched: readonly Fetched[]): FileCache =>
  Object.fromEntries(
    fetched.filter(({ text }) => text.kind !== 'unreadable').map(({ path, mtimeMs, text }) => [path, { mtimeMs, text }]),
  )

const fileIn = (entries: readonly FsEntry[] | null, folder: string, name: string): Wanted | null => {
  const entry = entries?.find(one => one.name === name && one.kind === 'file')
  return entry ? { path: `${folder}/${name}`, mtimeMs: entry.mtimeMs } : null
}

const roundNumbers = (entries: readonly FsEntry[] | null): number[] =>
  (entries ?? [])
    .filter(entry => entry.kind === 'dir')
    .map(entry => ROUND_FOLDER.exec(entry.name)?.[1])
    .filter((digits): digits is string => digits !== undefined)
    .map(Number)
    .sort((a, b) => a - b)

const parentOf = (path: string) => path.slice(0, path.lastIndexOf('/'))
const nameOf = (path: string) => path.slice(path.lastIndexOf('/') + 1)

export async function readRunFiles(
  $: EngineInterface,
  location: RunLocation,
  cache: FileCache,
): Promise<{ files: RunFiles; cache: FileCache }> {
  const { home, runDir, ledger } = location
  if (home === null || runDir === null || ledger === null) {
    return {
      files: {
        location,
        homeEntries: null,
        rounds: [],
        plan: ABSENT,
        planMtimeMs: null,
        state: ABSENT,
        laneNames: [],
        ledger: ABSENT,
      },
      cache: {},
    }
  }
  const [homeEntries, reviewEntries, runEntries, laneEntries, ledgerEntries] = await Promise.all([
    listing($, home),
    listing($, `${home}/review`),
    listing($, runDir),
    listing($, `${runDir}/lanes`),
    listing($, parentOf(ledger)),
  ])
  const numbers = roundNumbers(reviewEntries)
  const roundEntries = await Promise.all(numbers.map(n => listing($, `${home}/review/round-${n}`)))
  const roundFiles = numbers.flatMap((n, i) =>
    (roundEntries[i] ?? [])
      .filter(entry => entry.kind === 'file' && (VERDICT.test(entry.name) || FINDINGS.test(entry.name)))
      .map(entry => ({ path: `${home}/review/round-${n}/${entry.name}`, mtimeMs: entry.mtimeMs })),
  )
  const planFile = fileIn(runEntries, runDir, 'plan.json')
  const stateFile = fileIn(runEntries, runDir, 'state.json')
  const ledgerFile = fileIn(ledgerEntries, parentOf(ledger), nameOf(ledger))
  const wanted = [planFile, stateFile, ledgerFile, ...roundFiles].filter((one): one is Wanted => one !== null)
  const fetched = await fetchChanged($, wanted, cache)
  const textOf = (file: Wanted | null): FileText =>
    file === null ? ABSENT : (fetched.find(one => one.path === file.path)?.text ?? ABSENT)
  const rounds = numbers.map((n, i) => {
    const entries = (roundEntries[i] ?? []).filter(entry => entry.kind === 'file')
    const byLabel = (pattern: RegExp) =>
      Object.fromEntries(
        entries
          .filter(entry => pattern.test(entry.name))
          .map(entry => [pattern.exec(entry.name)?.[1] ?? '', textOf({ path: `${home}/review/round-${n}/${entry.name}`, mtimeMs: 0 })]),
      )
    return {
      n,
      names: entries.map(entry => entry.name),
      times: Object.fromEntries(entries.map(entry => [entry.name, entry.mtimeMs])),
      verdicts: byLabel(VERDICT),
      findings: byLabel(FINDINGS),
    }
  })
  return {
    files: {
      location,
      homeEntries,
      rounds,
      plan: textOf(planFile),
      planMtimeMs: planFile?.mtimeMs ?? null,
      state: textOf(stateFile),
      laneNames: (laneEntries ?? []).filter(entry => entry.kind === 'file').map(entry => entry.name),
      ledger: textOf(ledgerFile),
    },
    cache: cacheOf(fetched),
  }
}

files.hooks/run/infer.ts:
import type {
  Activity,
  FileFacts,
  LaneFact,
  MspRow,
  MspStatus,
  Outcome,
  RoundActivity,
  RoundFiles,
  RoundRow,
  RoundState,
  RunIdentity,
  RunView,
  Signals,
  Stage,
} from '../../types'
import type { FileText, ReviewRound, RunFiles } from './home'
import { isObject, parseJson } from './state'
import type { Json } from './state'
import { currentActivity, plural } from './summary'
import { workersOf } from './workers'

export const STAGES: readonly Stage[] = ['spec', 'build', 'review', 'fix', 'ship', 'integrate', 'clean']

const OUTCOMES: readonly Outcome[] = ['green', 'loop', 'diagnose', 'blocked', 'hard-failure']
const FAILED_LANE = new Set(['failed', 'blocked', 'merge-blocked'])
const OPEN_STATES: ReadonlySet<RoundState> = new Set(['suite running', 'reviewing', 'validating', 'diagnosing'])
const UNSHOWN_SOURCES = new Set(['suite', 'mitosis'])
const MOST_FINDING_LINES = 3

type Parsed<T> = { kind: 'absent' } | { kind: 'bad' } | { kind: 'ok'; value: T }

type PlanMsp = { label: string }
type PlanLane = { msp: number; tier: string }
type Plan = { msps: readonly PlanMsp[]; lanes: readonly PlanLane[] }

type StateShip = { branch: string | null; pullRequest: string; isPushed: boolean }
type StateGate = { properties: readonly Json[] }
type StateMsp = { state: string | null; gate: StateGate | null; ship: StateShip | null }
type RunState = {
  lanes: Readonly<Record<string, { state: string | null }>>
  msps: Readonly<Record<string, StateMsp>>
  worktrees: readonly { branch: string; msp: number; path: string | null }[]
}

type Verdict = { outcome: Outcome; blockers: readonly string[]; advisories: readonly string[] }

type RoundRead = {
  n: number
  state: RoundState
  verdict: Verdict | null
  startedAt: number | null
  verdictAt: number | null
}

const stringOr = <T>(value: unknown, fallback: T): string | T => (typeof value === 'string' ? value : fallback)

function parsed<T>(file: FileText, shape: (value: unknown) => T | null): Parsed<T> {
  if (file.kind === 'absent') return { kind: 'absent' }
  if (file.kind === 'unreadable') return { kind: 'bad' }
  const value = shape(parseJson(file.text))
  return value === null ? { kind: 'bad' } : { kind: 'ok', value }
}

function planShape(value: unknown): Plan | null {
  if (!isObject(value) || !Array.isArray(value.msps) || !Array.isArray(value.lanes)) return null
  const msps = value.msps.map(msp => (isObject(msp) && typeof msp.label === 'string' ? { label: msp.label } : null))
  const lanes = value.lanes.map(lane =>
    isObject(lane) && typeof lane.msp === 'number' ? { msp: lane.msp, tier: stringOr(lane.tier, '') } : null,
  )
  if (msps.some(msp => msp === null) || lanes.some(lane => lane === null)) return null
  return { msps: msps as PlanMsp[], lanes: lanes as PlanLane[] }
}

function shipShape(value: unknown): StateShip | null {
  if (!isObject(value)) return null
  return {
    branch: stringOr(value.branch, null),
    pullRequest: stringOr(value.pull_request, ''),
    isPushed: value.pushed !== null && value.pushed !== undefined,
  }
}

function gateShape(value: unknown): StateGate | null {
  if (!isObject(value)) return null
  return { properties: Array.isArray(value.properties) ? value.properties.filter(isObject) : [] }
}

function stateShape(value: unknown): RunState | null {
  if (!isObject(value) || !isObject(value.lanes) || !isObject(value.msps)) return null
  if (value.worktrees !== undefined && !Array.isArray(value.worktrees)) return null
  const lanes = Object.fromEntries(
    Object.entries(value.lanes).map(([n, lane]) => [n, { state: isObject(lane) ? stringOr(lane.state, null) : null }]),
  )
  const msps = Object.fromEntries(
    Object.entries(value.msps).map(([i, msp]) => [
      i,
      isObject(msp)
        ? { state: stringOr(msp.state, null), gate: gateShape(msp.gate), ship: shipShape(msp.ship) }
        : { state: null, gate: null, ship: null },
    ]),
  )
  const worktrees = (Array.isArray(value.worktrees) ? value.worktrees : [])
    .filter(isObject)
    .filter(tree => typeof tree.branch === 'string' && typeof tree.msp === 'number')
    .map(tree => ({ branch: tree.branch as string, msp: tree.msp as number, path: stringOr(tree.path, null) }))
  return { lanes, msps, worktrees }
}

const kindOf = (finding: unknown): string =>
  typeof finding === 'string' ? finding : isObject(finding) && typeof finding.kind === 'string' ? finding.kind : 'unnamed finding'

function verdictShape(value: unknown): Verdict | null {
  if (!isObject(value) || typeof value.outcome !== 'string') return null
  if (!Array.isArray(value.blockers) || !Array.isArray(value.advisories)) return null
  const outcome = OUTCOMES.find(one => one === value.outcome) ?? 'unknown'
  return { outcome, blockers: value.blockers.map(kindOf), advisories: value.advisories.map(kindOf) }
}

function findingsShape(value: unknown): readonly string[] | null {
  if (!Array.isArray(value)) return null
  return value.map(finding => (isObject(finding) && typeof finding.source === 'string' ? finding.source : ''))
}

function candidatesOf(ledger: FileText, slug: string): ReadonlyMap<string, number> {
  const lines = (ledger.kind === 'text' ? ledger.text : '').split('\n').map(line => parseJson(line))
  return new Map(
    lines
      .filter(isObject)
      .filter(line => line.type === 'round' && line.run === slug)
      .filter(line => typeof line.round === 'number' && typeof line.msp === 'string' && typeof line.findings === 'number')
      .map(line => [`${line.round}/${line.msp}`, line.findings as number]),
  )
}

const earliestOf = (times: readonly (number | null | undefined)[]): number | null => {
  const known = times.filter((time): time is number => typeof time === 'number')
  return known.length > 0 ? Math.min(...known) : null
}

const countWords = (verdict: Verdict) =>
  `${plural(verdict.blockers.length, 'blocker')}, ${plural(verdict.advisories.length, 'advisory')}`

function findingLines(blockers: readonly string[], advisories: readonly string[]): string[] {
  const lines = [...blockers.map(kind => `${kind} (blocker)`), ...advisories.map(kind => `${kind} (advisory)`)]
  if (lines.length <= MOST_FINDING_LINES) return lines
  return [...lines.slice(0, MOST_FINDING_LINES - 1), `+${lines.length - (MOST_FINDING_LINES - 1)} more`]
}

function outcomeParts(verdict: Verdict): { outcome: string; counts: string } {
  const hasFindings = verdict.blockers.length + verdict.advisories.length > 0
  if (verdict.outcome === 'green') return { outcome: 'Green', counts: hasFindings ? countWords(verdict) : 'no findings' }
  if (verdict.outcome === 'loop') return { outcome: 'Needs fixes', counts: countWords(verdict) }
  if (verdict.outcome === 'blocked') return { outcome: 'Blocked', counts: plural(verdict.blockers.length, 'blocker') }
  if (verdict.outcome === 'diagnose') return { outcome: 'Diagnosing', counts: plural(verdict.blockers.length, 'blocker') }
  return { outcome: 'Failed', counts: '' }
}

function outcomeLine(verdict: Verdict): string {
  const { outcome, counts } = outcomeParts(verdict)
  return counts === '' ? outcome : `${outcome} · ${counts}`
}

function verdictSummary(verdict: Verdict): string[] {
  return [outcomeLine(verdict), ...findingLines(verdict.blockers, verdict.outcome === 'diagnose' ? [] : verdict.advisories)]
}

const capitalised = (words: string) => words.charAt(0).toUpperCase() + words.slice(1)

const ownFiles = (round: ReviewRound, label: string): string[] =>
  round.names.filter(name => name.startsWith(`${label}.`))

function roundRead(round: ReviewRound, label: string, verdictOf: (round: ReviewRound, label: string) => Parsed<Verdict>): RoundRead | null {
  const own = ownFiles(round, label)
  if (own.length === 0) return null
  const startedAt = earliestOf(own.map(name => round.times[name]))
  const verdictName = `${label}.verdict.json`
  const verdictAt = round.times[verdictName] ?? null
  const base = { n: round.n, startedAt, verdictAt }
  if (own.includes(verdictName)) {
    const verdict = verdictOf(round, label)
    if (verdict.kind !== 'ok' || verdict.value.outcome === 'unknown') return { ...base, state: 'status unknown', verdict: null }
    const outcome = verdict.value.outcome
    return { ...base, state: outcome === 'diagnose' ? 'diagnosing' : outcome, verdict: verdict.value }
  }
  if (own.includes(`${label}.findings.json`)) return { ...base, state: 'validating', verdict: null }
  if (own.includes(`${label}.suite.txt`)) return { ...base, state: 'reviewing', verdict: null }
  return { ...base, state: 'suite running', verdict: null }
}

function roundActivity(read: RoundRead): RoundActivity {
  const isOpen = OPEN_STATES.has(read.state)
  return {
    kind: 'round',
    round: read.n,
    name: `Round ${read.n}`,
    words: `Round ${read.n} · ${read.state}`,
    state: read.state,
    isRunning: isOpen,
    startedAt: read.state === 'diagnosing' ? (read.verdictAt ?? read.startedAt) : read.startedAt,
    summary:
      read.verdict !== null
        ? verdictSummary(read.verdict)
        : read.state === 'status unknown'
          ? ['Result unreadable']
          : [capitalised(read.state)],
    kinds: read.verdict === null ? [] : [...read.verdict.blockers, ...read.verdict.advisories],
    counts: read.verdict === null ? '' : outcomeParts(read.verdict).counts,
  }
}

function fixActivity(read: RoundRead, verdict: Verdict, isFixed: boolean): Activity {
  return {
    kind: 'fix',
    round: read.n,
    name: `Fix after round ${read.n}`,
    words: `Fix after round ${read.n}`,
    state: null,
    isRunning: !isFixed,
    startedAt: read.verdictAt,
    summary: [`Fixing ${countWords(verdict)}`, ...findingLines(verdict.blockers, [])],
    kinds: [...verdict.blockers, ...verdict.advisories],
  }
}

const shipActivity = (words: string, summary: readonly string[], kinds: readonly string[] = []): Activity => ({
  kind: 'ship',
  round: null,
  name: 'Ship',
  words: `Ship · ${words}`,
  state: null,
  isRunning: false,
  startedAt: null,
  summary,
  kinds,
})

const pullShip = (pr: string) => shipActivity(`pull request ${pr}`, [`Pull request ${pr} open`])

function shipAfter(last: RoundRead | undefined): Activity | null {
  const verdict = last?.verdict
  if (verdict === null || verdict === undefined) return null
  if (verdict.outcome === 'green') return shipActivity('waiting for pull request', ['Waiting for pull request'])
  if (verdict.outcome === 'blocked') {
    return shipActivity(
      'draft',
      [`Draft · ${plural(verdict.blockers.length, 'blocker')}`, ...findingLines(verdict.blockers, [])],
      verdict.blockers,
    )
  }
  return null
}

type BuildFacts = {
  lanes: readonly LaneFact[]
  lanesDone: number
  lanesTotal: number
  isCommitted: boolean
  proof: MspRow['proof']
  startedAt: number | null
}

function buildActivity(build: BuildFacts, hasRounds: boolean): Activity {
  const failed = build.lanes.filter(lane => lane.state === 'failed')
  const isBuilt =
    build.isCommitted || hasRounds || (build.lanesTotal > 0 && build.lanesDone === build.lanesTotal && failed.length === 0)
  const gate =
    build.proof === null
      ? []
      : [build.proof.isRedSeen && build.proof.isGreenSeen ? 'Gate passed · failed without the work, passed with it' : 'Gate inconclusive']
  const lanes = build.lanesTotal === 1 ? 'lane' : 'lanes'
  return {
    kind: 'build',
    round: null,
    name: 'Build',
    words:
      failed.length > 0 && !hasRounds
        ? 'Build · failed'
        : isBuilt
          ? 'Build · done'
          : `Build · ${build.lanesDone} of ${build.lanesTotal} ${lanes}`,
    state: null,
    isRunning: !isBuilt && failed.length === 0,
    startedAt: build.startedAt,
    summary: [`${build.lanesDone} of ${build.lanesTotal} ${lanes} done`, ...gate, ...failed.map(lane => `Lane ${lane.n} failed`)].slice(0, 4),
    kinds: [],
  }
}

const roundActivities = (reads: readonly RoundRead[]): Activity[] =>
  reads.flatMap((read, i) => {
    const isFixed = i < reads.length - 1
    return read.verdict?.outcome === 'loop' ? [roundActivity(read), fixActivity(read, read.verdict, isFixed)] : [roundActivity(read)]
  })

function activitiesOf(build: BuildFacts, reads: readonly RoundRead[], pr: string): Activity[] {
  const ship = pr !== '' ? pullShip(pr) : shipAfter(reads[reads.length - 1])
  return [buildActivity(build, reads.length > 0), ...roundActivities(reads), ...(ship === null ? [] : [ship])]
}

const withPullShip = (activities: readonly Activity[], pr: string): Activity[] => [
  ...activities.filter(activity => activity.kind !== 'ship'),
  pullShip(pr),
]

function stageOfActivity(activity: Activity | undefined): Stage | 'unknown' {
  if (activity === undefined) return 'unknown'
  if (activity.kind === 'build') return 'build'
  if (activity.kind === 'fix') return 'fix'
  if (activity.kind === 'ship') return 'ship'
  if (activity.state === 'diagnosing') return 'fix'
  if (activity.state === 'status unknown') return 'unknown'
  return 'review'
}

function statusOf(
  label: string,
  laneStates: readonly (string | null | undefined)[],
  laneOuts: readonly boolean[],
  msp: StateMsp | undefined,
  rounds: readonly ReviewRound[],
  verdictOf: (round: ReviewRound, label: string) => Parsed<Verdict>,
): { status: MspStatus; round: number } {
  const reviewed = rounds.filter(round => round.names.includes(`${label}.diff`))
  const judged = rounds.filter(round => round.verdicts[label] !== undefined)
  const reviewRound = reviewed[reviewed.length - 1]?.n ?? 0
  const latestJudged = judged[judged.length - 1]
  const round = Math.max(reviewRound, latestJudged?.n ?? 0)
  if (laneStates.some(state => typeof state === 'string' && FAILED_LANE.has(state))) return { status: 'failed', round }
  if ((msp?.ship?.pullRequest ?? '') !== '') return { status: 'pr', round }
  if (latestJudged !== undefined && latestJudged.n >= reviewRound) {
    const verdict = verdictOf(latestJudged, label)
    if (verdict.kind === 'bad') return { status: 'unknown', round }
    if (verdict.kind === 'ok') {
      const outcome = verdict.value.outcome
      if (outcome === 'green') return { status: 'green', round }
      if (outcome === 'blocked') return { status: 'blocked', round }
      if (outcome === 'loop' || outcome === 'diagnose') return { status: 'fixing', round }
    }
  }
  if (reviewRound > 0) return { status: 'review', round }
  if (msp?.state === 'committed') return { status: 'built', round }
  if (laneStates.some((state, i) => state === undefined && laneOuts[i] === true)) return { status: 'building', round }
  return { status: 'planned', round }
}

const slugOf = (words: string) => words.trim().toLowerCase().replace(/\s+/g, '-')

function diagnosisWords(slug: string, kinds: readonly string[]): string {
  return kinds.find(kind => slugOf(kind) === slug) ?? slug.replace(/-/g, ' ')
}

function roundFilesOf(round: ReviewRound, label: string, kinds: readonly string[]): RoundFiles {
  const own = ownFiles(round, label).map(name => name.slice(label.length + 1))
  const findings = parsed(round.findings[label] ?? { kind: 'absent' }, findingsShape)
  const sources = findings.kind === 'ok' ? findings.value.filter(source => source !== '' && !UNSHOWN_SOURCES.has(source)) : []
  const counted = [...new Set(sources)].map(source => ({ source, count: sources.filter(one => one === source).length }))
  return {
    n: round.n,
    msp: label,
    findingSources: findings.kind === 'bad' ? null : counted,
    candidates: findings.kind === 'ok' ? findings.value.length : null,
    diagnoses: own
      .map(name => /^(.+)\.diagnosis\.json$/.exec(name)?.[1])
      .filter((slug): slug is string => slug !== undefined)
      .map(slug => diagnosisWords(slug, kinds)),
    smokes: own
      .map(name => /^smoke-(.+)\.txt$/.exec(name)?.[1])
      .filter((platform): platform is string => platform !== undefined),
  }
}

function laneFactOf(lane: PlanLane & { n: number; hasOut: boolean }, label: string, ended: { state: string | null } | undefined): LaneFact | null {
  if (ended !== undefined) {
    const isFailed = typeof ended.state === 'string' && FAILED_LANE.has(ended.state)
    return { n: lane.n, msp: label, tier: lane.tier, state: isFailed ? 'failed' : 'done' }
  }
  return lane.hasOut ? { n: lane.n, msp: label, tier: lane.tier, state: 'building' } : null
}

export function inferFacts(files: RunFiles): FileFacts {
  const { location } = files
  const plan = parsed(files.plan, planShape)
  const state = parsed(files.state, stateShape)
  const verdictOf = (round: ReviewRound, label: string): Parsed<Verdict> =>
    parsed(round.verdicts[label] ?? { kind: 'absent' }, verdictShape)
  const lastRound = files.rounds[files.rounds.length - 1]
  const highestRound = lastRound?.n ?? 0
  const outs = new Set(files.laneNames.filter(name => name.endsWith('.out')).map(name => name.slice(0, -'.out'.length)))
  const lanes = plan.kind === 'ok' ? plan.value.lanes.map((lane, n) => ({ ...lane, n, hasOut: outs.has(String(n)) })) : []
  const runState = state.kind === 'ok' ? state.value : null
  const entryOf = (n: number) => runState?.lanes[String(n)]
  const labels = plan.kind === 'ok' ? plan.value.msps.map(msp => msp.label) : []
  const laneFacts =
    state.kind === 'bad'
      ? []
      : lanes
          .map(lane => laneFactOf(lane, labels[lane.msp] ?? '', entryOf(lane.n)))
          .filter((lane): lane is LaneFact => lane !== null && lane.msp !== '')
  const readsOf = (label: string) =>
    files.rounds.map(round => roundRead(round, label, verdictOf)).filter((read): read is RoundRead => read !== null)
  const msps = labels.map((label, i): MspRow => {
    const own = lanes.filter(lane => lane.msp === i)
    const msp = runState?.msps[String(i)]
    const tree = runState?.worktrees.find(one => one.msp === i)
    const known = statusOf(
      label,
      own.map(lane => (entryOf(lane.n) === undefined ? undefined : (entryOf(lane.n)?.state ?? null))),
      own.map(lane => lane.hasOut),
      msp,
      files.rounds,
      verdictOf,
    )
    const properties = msp?.gate?.properties ?? []
    const proof =
      msp?.gate === null || msp?.gate === undefined
        ? null
        : {
            isRedSeen: properties.some(property => property.outcome === 'pass'),
            isGreenSeen: properties.some(property => property.with_work === 0),
          }
    const lanesDone = own.filter(lane => entryOf(lane.n) !== undefined).length
    const pr = msp?.ship?.pullRequest ?? ''
    const facts = {
      label,
      branch: tree?.branch ?? `mitosis/${label}`,
      shipBranch: msp?.ship?.branch ?? null,
      lanesDone,
      lanesTotal: own.length,
      tier: own[0]?.tier ?? '',
      round: known.round,
      pr,
      proof,
    }
    if (state.kind === 'bad') {
      return { ...facts, status: 'unknown', activities: roundActivities(readsOf(label)), current: null, stage: 'unknown' }
    }
    const activities = activitiesOf(
      {
        lanes: laneFacts.filter(lane => lane.msp === label),
        lanesDone,
        lanesTotal: own.length,
        isCommitted: msp?.state === 'committed',
        proof,
        startedAt: files.planMtimeMs,
      },
      readsOf(label),
      pr,
    )
    const current = activities.length - 1
    return { ...facts, status: known.status, activities, current, stage: stageOfActivity(activities[current]) }
  })
  const building = laneFacts.filter(lane => lane.state === 'building')
  const candidates = candidatesOf(files.ledger, location.slug)
  const order = (label: string) => {
    const at = labels.indexOf(label)
    return at === -1 ? labels.length : at
  }
  const roundFiles: RoundFiles[] = files.rounds.flatMap(round =>
    labels
      .filter(label => ownFiles(round, label).length > 0)
      .map(label => {
        const verdict = verdictOf(round, label)
        return roundFilesOf(round, label, verdict.kind === 'ok' ? [...verdict.value.blockers, ...verdict.value.advisories] : [])
      }),
  )
  const rounds: RoundRow[] = files.rounds.flatMap(round =>
    Object.keys(round.verdicts)
      .sort((a, b) => order(a) - order(b) || a.localeCompare(b))
      .map(label => {
        const verdict = verdictOf(round, label)
        const listed = roundFiles.find(one => one.n === round.n && one.msp === label)?.candidates ?? null
        return {
          n: round.n,
          msp: label,
          candidates: candidates.get(`${round.n}/${label}`) ?? listed,
          blockers: verdict.kind === 'ok' ? verdict.value.blockers.length : 0,
          advisories: verdict.kind === 'ok' ? verdict.value.advisories.length : 0,
          outcome: verdict.kind === 'ok' ? verdict.value.outcome : 'unknown',
        }
      }),
  )
  const fileTimes = (files.homeEntries ?? []).filter(entry => entry.kind === 'file').map(entry => entry.mtimeMs)
  return {
    slug: location.slug,
    repo: location.repo,
    home: location.home,
    runDir: location.runDir,
    hasPlan: plan.kind,
    isStateBad: state.kind === 'bad',
    hasLighthouse: (files.homeEntries ?? []).some(entry => entry.name === 'lighthouse' && entry.kind === 'dir'),
    highestRound,
    msps,
    rounds,
    roundFiles,
    lanes: laneFacts,
    worktrees: (runState?.worktrees ?? [])
      .map(tree => ({ msp: labels[tree.msp] ?? '', path: tree.path ?? '' }))
      .filter(tree => tree.msp !== '' && tree.path !== ''),
    buildingLanes: building.length,
    buildingTier: building[0]?.tier ?? '',
    oldestMtimeMs: fileTimes.length > 0 ? Math.min(...fileTimes) : null,
  }
}

const isAtLeast = (stage: Stage | null, floor: Stage) => stage !== null && STAGES.indexOf(stage) >= STAGES.indexOf(floor)

function mspStage(msps: readonly MspRow[]): Stage | 'unknown' {
  const unshipped = msps.filter(msp => msp.pr === '')
  if (unshipped.some(msp => msp.stage === 'unknown')) return 'unknown'
  const stages = unshipped.map(msp => STAGES.indexOf(msp.stage as Stage))
  if (stages.length === 0) return msps.length === 0 ? 'build' : 'ship'
  return STAGES[Math.min(...stages)] ?? 'unknown'
}

function stageOf(files: FileFacts, msps: readonly MspRow[], signals: Signals): Stage | 'unknown' {
  const call = signals.callStage
  if (call === 'clean') return 'clean'
  if (call === 'integrate' || files.hasLighthouse) return 'integrate'
  if (files.home === null) return call === null ? 'unknown' : isAtLeast(call, 'build') ? 'build' : call
  if (files.hasPlan === 'bad') return 'unknown'
  if (files.hasPlan === 'absent') return isAtLeast(call, 'build') ? 'build' : 'spec'
  if (files.isStateBad) return 'unknown'
  return mspStage(msps)
}

function roundOf(stage: Stage | 'unknown', msps: readonly MspRow[], highestRound: number): number {
  if (stage === 'unknown') return highestRound
  if (stage !== 'review' && stage !== 'fix') return 0
  const rounds = msps
    .filter(msp => msp.pr === '' && msp.stage === stage)
    .map(msp => currentActivity(msp)?.round ?? 0)
  return rounds.length > 0 ? Math.max(...rounds) : highestRound
}

function withPull(msp: MspRow, signals: Signals): MspRow {
  if (msp.pr !== '') return msp.status === 'failed' ? msp : { ...msp, status: 'pr' }
  const pull = signals.pulls.find(one => one.head === msp.shipBranch || one.head === msp.branch)
  if (pull === undefined) return msp
  const pr = `#${pull.number}`
  const activities = withPullShip(msp.activities, pr)
  return {
    ...msp,
    pr,
    status: msp.status === 'failed' ? 'failed' : 'pr',
    activities,
    current: activities.length - 1,
    stage: 'ship',
  }
}

export const isSameRun = (one: RunIdentity, other: RunIdentity) => one.slug === other.slug && one.home === other.home

export const isRunStarted = (files: FileFacts | null, signals: Signals) =>
  signals.callStage !== null || (files?.home ?? null) !== null

export function buildView(files: FileFacts | null, signals: Signals): RunView | null {
  if (files === null || !isRunStarted(files, signals)) return null
  if (signals.finishedRun != null && isSameRun(signals.finishedRun, files)) return null
  const msps = files.msps.map(msp => withPull(msp, signals))
  const stage = stageOf(files, msps, signals)
  return {
    slug: files.slug,
    repo: files.repo,
    home: files.home,
    stage,
    round: roundOf(stage, msps, files.highestRound),
    isFinished: signals.isCleanDone,
    lane: signals.lane,
    startedAt: earliestOf([files.oldestMtimeMs, signals.firstCallAt]),
    msps,
    rounds: files.rounds,
    agents: signals.agents,
    workers: workersOf(files, msps, signals),
    buildingLanes: files.buildingLanes,
    buildingTier: files.buildingTier,
    costUsd: signals.costUsd,
    isPullRequestRunning: signals.isPullRequestRunning,
  }
}

files.hooks/run/session.ts:
import type { EngineInterface } from 'claude-code'

import { isObject, parseJson } from './state'

export type RunLocation = {
  slug: string
  repo: string | null
  home: string | null
  runDir: string | null
  ledger: string | null
}

export type SessionFile = { mitosis: string; path: string }

type RunHome = { path: string; anchor: unknown }

const isRunHome = (value: unknown): value is RunHome => isObject(value) && typeof value.path === 'string'

const segments = (path: string) => path.split('/').filter(part => part !== '')

export async function sessionFile($: EngineInterface): Promise<SessionFile | null> {
  const home = await $.env.get('HOME')
  if (home === undefined || home === '') return null
  const id = await $.session.id()
  const mitosis = `${home.replace(/\/+$/, '')}/.mitosis`
  return { mitosis, path: `${mitosis}/sessions/${id}.json` }
}

export function locate(text: string | null, mitosis: string): RunLocation | null {
  if (text === null) return null
  const session = parseJson(text)
  if (!isObject(session)) return null
  const thread = typeof session.thread_id === 'string' && session.thread_id !== '' ? session.thread_id : null
  const homes = Array.isArray(session.run_homes) ? session.run_homes.filter(isRunHome) : []
  const candidates =
    thread === null
      ? homes
      : homes.filter(entry => typeof entry.anchor === 'string' && entry.anchor.includes(`, thread ${thread}: `))
  const chosen = candidates.find(entry => entry.anchor === session.latest_anchor) ?? candidates[0]
  if (chosen === undefined) {
    return thread === null ? null : { slug: thread, repo: null, home: null, runDir: null, ledger: null }
  }
  const parts = segments(chosen.path)
  const slug = parts[parts.length - 1]
  const repo = parts[parts.length - 2]
  if (slug === undefined || repo === undefined) return null
  return {
    slug,
    repo,
    home: chosen.path.replace(/\/+$/, ''),
    runDir: `${mitosis}/runs/${repo}/${slug}`,
    ledger: `${mitosis}/${repo}/findings.jsonl`,
  }
}

files.hooks/run/command.ts:
export type SimpleCommand = {
  readonly assignments: Readonly<Record<string, string>>
  readonly words: readonly string[]
  readonly decidesStatus: boolean
}

const SEPARATORS = new Set([';', '&', '|', '\n', '(', ')'])
const BLANK = /\s/
const ASSIGNMENT = /^([A-Za-z_][A-Za-z0-9_]*)=([\s\S]*)$/
const PREFIX_ASSIGNMENT = /^([A-Za-z_][A-Za-z0-9_]*)\+?=/
const SHELLS = new Set(['zsh', 'bash', 'sh'])
const MODIFIERS = new Set(['command', 'builtin', 'exec', 'noglob', 'nocorrect'])

type Heredoc = { readonly delimiter: string; readonly stripsTabs: boolean }

function heredocDelimiter(text: string, from: number): { readonly heredoc: Heredoc; readonly end: number } {
  let index = from
  const stripsTabs = text[index] === '-'
  if (stripsTabs) index += 1
  while (text[index] === ' ' || text[index] === '\t') index += 1
  let delimiter = ''
  let quote: string | null = null
  for (; index < text.length; index += 1) {
    const char = text[index]!
    if (quote !== null) {
      if (char === quote) quote = null
      else delimiter += char
      continue
    }
    if (char === "'" || char === '"') quote = char
    else if (char === '\\' && index + 1 < text.length) delimiter += text[++index]!
    else if (BLANK.test(char) || SEPARATORS.has(char) || char === '<' || char === '>') break
    else delimiter += char
  }
  return { heredoc: { delimiter, stripsTabs }, end: index - 1 }
}

function skipHeredocBodies(text: string, newline: number, pending: readonly Heredoc[]): number {
  let lineStart = newline + 1
  for (const { delimiter, stripsTabs } of pending) {
    while (lineStart <= text.length) {
      const found = text.indexOf('\n', lineStart)
      const lineEnd = found === -1 ? text.length : found
      const line = text.slice(lineStart, lineEnd)
      lineStart = lineEnd + 1
      if ((stripsTabs ? line.replace(/^\t+/, '') : line) === delimiter) break
    }
  }
  return lineStart - 1
}

type Word = { readonly value: string; readonly raw: string }

type Scope = readonly string[]

type Parsed = {
  readonly words: readonly Word[]
  readonly scope: Scope
  readonly follows: string | null
  readonly isQuiet: boolean
  readonly isPiped: boolean
  readonly isNested: boolean
}

type Scan = { readonly end: number; readonly records: readonly Parsed[] }

type Span = { readonly from: number; readonly to: number }

const nested = (records: readonly Parsed[]): readonly Parsed[] =>
  records.map(record => ({ ...record, isQuiet: true, isNested: true }))

function escapedEnd(text: string, from: number, closer: string): number {
  for (let index = from; index < text.length; index += 1) {
    if (text[index] === '\\') index += 1
    else if (text[index] === closer) return index
  }
  return -1
}

function scanUntil(text: string, from: number, closer: string, nestsParens: boolean, scope: Scope): Scan | null {
  let depth = 0
  let records: readonly Parsed[] = []
  for (let index = from; index < text.length; index += 1) {
    const char = text[index]!
    if (char === '\\') {
      index += 1
      continue
    }
    if (char === closer && depth === 0) return { end: index, records }
    if (nestsParens && (char === '(' || char === ')')) {
      depth += char === '(' ? 1 : -1
      continue
    }
    const quoted = quotedAt(text, index, scope)
    if (quoted === null) return null
    if (quoted !== undefined) {
      records = [...records, ...quoted.records]
      index = quoted.end
    }
  }
  return null
}

function doubleQuoted(text: string, open: number, scope: Scope): Scan | null {
  let records: readonly Parsed[] = []
  for (let index = open + 1; index < text.length; index += 1) {
    const char = text[index]!
    if (char === '\\') {
      index += 1
      continue
    }
    if (char === '"') return { end: index, records }
    const expansion = expansionAt(text, index, scope)
    if (expansion === null) return null
    if (expansion !== undefined) {
      records = [...records, ...expansion.records]
      index = expansion.end
    }
  }
  return null
}

type Quote = Scan & { readonly value: string }

const closedQuote = (end: number, value: (end: number) => string): Quote | null =>
  end === -1 ? null : { end, records: [], value: value(end) }

function quoteAt(text: string, index: number, scope: Scope): Quote | null | undefined {
  const char = text[index]
  if (char === "'") return closedQuote(text.indexOf("'", index + 1), end => text.slice(index + 1, end))
  if (char === '"') {
    const scan = doubleQuoted(text, index, scope)
    return scan === null ? null : { ...scan, value: unquotedDouble(text.slice(index + 1, scan.end)) }
  }
  if (char === '$' && text[index + 1] === "'") {
    return closedQuote(escapedEnd(text, index + 2, "'"), end => text.slice(index + 2, end).replace(/\\([\s\S])/g, '$1'))
  }
  return undefined
}

function quotedAt(text: string, index: number, scope: Scope): Scan | null | undefined {
  const quote = quoteAt(text, index, scope)
  return quote === undefined ? expansionAt(text, index, scope) : quote
}

function expansionAt(text: string, index: number, scope: Scope): Scan | null | undefined {
  const char = text[index]
  const next = text[index + 1]
  if (char === '`') return backquoted(text, index, scope)
  if (char !== '$') return undefined
  if (next === '{') return scanUntil(text, index + 2, '}', false, scope)
  if (next === '[') return scanUntil(text, index + 2, ']', false, scope)
  if (next !== '(') return undefined
  if (text[index + 2] === '(') return arithmetic(text, index + 1, scope) ?? substituted(text, index + 2, scope)
  return substituted(text, index + 2, scope)
}

function arithmetic(text: string, open: number, scope: Scope): Scan | null {
  const inner = scanUntil(text, open + 2, ')', true, scope)
  return inner !== null && text[inner.end + 1] === ')' ? { end: inner.end + 1, records: inner.records } : null
}

function substituted(text: string, from: number, scope: Scope): Scan | null {
  const script = parseScript(text, from, ')', [...scope, `$${from}`])
  return script === null ? null : { end: script.end, records: nested(script.records) }
}

function backquoted(text: string, open: number, scope: Scope): Scan | null {
  const end = escapedEnd(text, open + 1, '`')
  if (end === -1) return null
  const inner = text.slice(open + 1, end).replace(/\\([\\`$])/g, '$1')
  const script = parseScript(inner, 0, null, [...scope, `\`${open}`])
  return script === null ? null : { end, records: nested(script.records) }
}

const unquotedDouble = (inner: string) => inner.replace(/\\\n/g, '').replace(/\\([$`"\\])/g, '$1')

function nextNonBlank(text: string, from: number): number {
  let index = from
  while (text[index] === ' ' || text[index] === '\t') index += 1
  return index
}

const within = (spans: readonly Span[], at: number) => spans.some(span => at >= span.from && at < span.to)

type FrameKind = 'base' | 'subshell' | 'brace' | 'if' | 'loop' | 'case'

type FrameMode = 'commands' | 'header' | 'subject' | 'pattern'

type Frame = {
  readonly kind: FrameKind
  readonly scope: Scope
  readonly isDefinition: boolean
  readonly mode: FrameMode
  readonly pipelineStart: number
  readonly elementStart: number
  readonly isPipedIn: boolean
  readonly negatedFrom: number | null
  readonly conditionFrom: number | null
}

type Script = { readonly records: readonly Parsed[]; readonly end: number }

function parseScript(text: string, from: number, closer: ')' | null, scope: Scope): Script | null {
  let records: readonly Parsed[] = []
  let quietSpans: readonly Span[] = []
  let pipedSpans: readonly Span[] = []
  let frames: readonly Frame[] = [
    {
      kind: 'base',
      scope,
      isDefinition: false,
      mode: 'commands',
      pipelineStart: 0,
      elementStart: 0,
      isPipedIn: false,
      negatedFrom: null,
      conditionFrom: null,
    },
  ]
  let words: readonly Word[] = []
  let value: string | null = null
  let raw = ''
  let pending: readonly Heredoc[] = []
  let follows: string | null = null
  let isRedirecting = false
  let isAfterTime = false
  let definition: 'none' | 'name' | 'body' = 'none'
  let isBroken = false
  let isAtLinebreak = true
  let index = from

  const top = () => frames[frames.length - 1]!
  const setTop = (change: Partial<Frame>) => {
    frames = [...frames.slice(0, -1), { ...top(), ...change }]
  }
  const append = (rawPart: string, valuePart: string) => {
    raw += rawPart
    value = (value ?? '') + valuePart
  }
  const appendScan = (scan: Scan) => {
    if (!top().isDefinition) records = [...records, ...scan.records]
    const scanned = text.slice(index, scan.end + 1)
    append(scanned, scanned)
    index = scan.end
  }
  const open = (kind: FrameKind, mode: FrameMode, conditionFrom: number | null) => {
    const outer = top()
    frames = [
      ...frames,
      {
        kind,
        scope: kind === 'subshell' ? [...outer.scope, `(${index}`] : outer.scope,
        isDefinition: outer.isDefinition || definition === 'body',
        mode,
        pipelineStart: records.length,
        elementStart: records.length,
        isPipedIn: false,
        negatedFrom: null,
        conditionFrom,
      },
    ]
    definition = 'none'
    isAtLinebreak = true
  }
  const endCondition = () => {
    const { conditionFrom } = top()
    if (conditionFrom !== null) quietSpans = [...quietSpans, { from: conditionFrom, to: records.length }]
    setTop({ conditionFrom: null })
  }
  const endPipeline = () => {
    const frame = top()
    const to = records.length
    if (frame.isPipedIn) pipedSpans = [...pipedSpans, { from: frame.elementStart, to }]
    if (frame.negatedFrom !== null) quietSpans = [...quietSpans, { from: frame.negatedFrom, to }]
    setTop({ pipelineStart: to, elementStart: to, isPipedIn: false, negatedFrom: null })
  }
  const close = (kind: FrameKind) => {
    if (top().kind !== kind) {
      isBroken = true
      return
    }
    endPipeline()
    endCondition()
    frames = frames.slice(0, -1)
    isAtLinebreak = false
  }
  const expectFrame = (kind: FrameKind, then: () => void) => {
    if (top().kind === kind) then()
    else isBroken = true
  }
  const isReserved = (word: string): boolean => {
    switch (word) {
      case '!':
        if (top().negatedFrom === null) setTop({ negatedFrom: records.length })
        return true
      case 'time':
        isAfterTime = true
        return true
      case '{':
        open('brace', 'commands', null)
        return true
      case '}':
        close('brace')
        return true
      case 'if':
        open('if', 'commands', records.length)
        return true
      case 'while':
      case 'until':
        open('loop', 'commands', records.length)
        return true
      case 'for':
      case 'select':
        open('loop', 'header', null)
        return true
      case 'case':
        open('case', 'subject', null)
        return true
      case 'elif':
        expectFrame('if', () => setTop({ conditionFrom: records.length }))
        isAtLinebreak = true
        return true
      case 'then':
        expectFrame('if', endCondition)
        isAtLinebreak = true
        return true
      case 'else':
        expectFrame('if', () => undefined)
        isAtLinebreak = true
        return true
      case 'do':
        expectFrame('loop', endCondition)
        isAtLinebreak = true
        return true
      case 'fi':
        close('if')
        return true
      case 'done':
        close('loop')
        return true
      case 'esac':
        close('case')
        return true
      case 'function':
        definition = 'name'
        return true
      default:
        return false
    }
  }
  const finishWord = () => {
    if (value === null) return
    isAtLinebreak = false
    const word: Word = { value, raw }
    value = null
    raw = ''
    if (isRedirecting) {
      isRedirecting = false
      return
    }
    const { mode } = top()
    if (mode === 'subject') {
      if (word.raw === 'in') setTop({ mode: 'pattern' })
      return
    }
    if (mode === 'pattern') {
      if (word.raw === 'esac') close('case')
      return
    }
    if (mode === 'header') {
      if (word.raw === 'do') setTop({ mode: 'commands' })
      return
    }
    if (definition === 'name') {
      definition = 'body'
      return
    }
    if (words.length === 0) {
      const followsTime = isAfterTime
      isAfterTime = false
      if (followsTime && word.raw === '-p') return
      if (isReserved(word.raw)) return
    }
    definition = 'none'
    words = [...words, word]
  }
  const finishCommand = () => {
    finishWord()
    isRedirecting = false
    isAfterTime = false
    if (words.length > 0 && !top().isDefinition) {
      records = [...records, { words, scope: top().scope, follows, isQuiet: false, isPiped: false, isNested: false }]
    }
    words = []
  }
  const finishBeforeRedirect = () => {
    if (value !== null && /^\d+$/.test(raw)) {
      value = null
      raw = ''
    } else finishWord()
  }
  const pipe = () => {
    finishCommand()
    if (top().mode === 'pattern') return
    const span = { from: top().elementStart, to: records.length }
    quietSpans = [...quietSpans, span]
    pipedSpans = [...pipedSpans, span]
    setTop({ elementStart: records.length, isPipedIn: true })
    isAtLinebreak = true
  }
  const list = (operator: string) => {
    finishCommand()
    if (operator === '&') quietSpans = [...quietSpans, { from: top().pipelineStart, to: records.length }]
    endPipeline()
    follows = operator
    isAtLinebreak = true
    if (operator === ';;' || operator === ';;&' || operator === ';&') {
      if (top().kind === 'case' && top().mode === 'commands') setTop({ mode: 'pattern' })
      else isBroken = true
    }
  }
  const script = (end: number): Script | null => {
    if (isBroken || frames.length > 1) return null
    endPipeline()
    return {
      end,
      records: records.map((record, at) => ({
        ...record,
        isQuiet: record.isQuiet || within(quietSpans, at),
        isPiped: record.isPiped || within(pipedSpans, at),
      })),
    }
  }

  for (; index < text.length; index += 1) {
    const char = text[index]!
    const next = text[index + 1]
    if (char === '\\') {
      if (next === undefined) append(char, char)
      else if (next !== '\n') append(char + next, next)
      index += 1
      continue
    }
    const quote = quoteAt(text, index, top().scope)
    if (quote === null) return null
    if (quote !== undefined) {
      if (!top().isDefinition) records = [...records, ...quote.records]
      append(text.slice(index, quote.end + 1), quote.value)
      index = quote.end
      continue
    }
    const expansion = expansionAt(text, index, top().scope)
    if (expansion === null) return null
    if (expansion !== undefined) {
      appendScan(expansion)
      continue
    }
    if (char === '#' && value === null) {
      const found = text.indexOf('\n', index)
      index = (found === -1 ? text.length : found) - 1
      continue
    }
    if (text.startsWith('<<<', index)) {
      finishBeforeRedirect()
      isRedirecting = true
      index += 2
      continue
    }
    if (char === '<' && next === '<') {
      finishBeforeRedirect()
      const { heredoc, end } = heredocDelimiter(text, index + 2)
      pending = [...pending, heredoc]
      index = end
      continue
    }
    if ((char === '<' || char === '>') && next === '(') {
      const scan = substituted(text, index + 2, top().scope)
      if (scan === null) return null
      appendScan(scan)
      continue
    }
    if (char === '<' || char === '>') {
      finishBeforeRedirect()
      isRedirecting = true
      if (next === '>' || next === '&' || next === '|') index += 1
      continue
    }
    if (char === '&' && next === '>') {
      finishBeforeRedirect()
      isRedirecting = true
      index += text[index + 2] === '>' ? 2 : 1
      continue
    }
    if (char === '&' && next === '&') {
      list('&&')
      index += 1
      continue
    }
    if (char === '|' && next === '|') {
      list('||')
      index += 1
      continue
    }
    if (char === '|') {
      pipe()
      if (next === '&') index += 1
      continue
    }
    if (char === '&') {
      list('&')
      continue
    }
    if (char === ';') {
      const operator = next === ';' ? (text[index + 2] === '&' ? ';;&' : ';;') : next === '&' ? ';&' : ';'
      list(operator)
      index += operator.length - 1
      continue
    }
    if (char === '\n') {
      finishWord()
      if (!isAtLinebreak) list('\n')
      if (pending.length > 0) {
        index = skipHeredocBodies(text, index, pending)
        pending = []
      }
      continue
    }
    if (char === '(') {
      if (top().mode === 'pattern') {
        finishWord()
        continue
      }
      if (value === null && next === '(') {
        const scan = arithmetic(text, index, top().scope)
        if (scan !== null) {
          appendScan(scan)
          continue
        }
      }
      if (value !== null || words.length > 0 || definition === 'body') {
        const closing = nextNonBlank(text, index + 1)
        if (text[closing] === ')') {
          value = null
          raw = ''
          words = []
          definition = 'body'
          index = closing
          continue
        }
        if (definition !== 'body') {
          const scan = scanUntil(text, index + 1, ')', true, top().scope)
          if (scan === null) return null
          appendScan(scan)
          continue
        }
      }
      open('subshell', 'commands', null)
      continue
    }
    if (char === ')') {
      if (top().mode === 'pattern') {
        finishWord()
        if (top().mode === 'pattern') {
          setTop({ mode: 'commands' })
          continue
        }
      }
      finishCommand()
      if (top().kind === 'subshell') {
        close('subshell')
        continue
      }
      if (closer === ')' && frames.length === 1) return script(index)
      return null
    }
    if (BLANK.test(char)) {
      finishWord()
      continue
    }
    append(char, char)
  }
  if (closer !== null) return null
  finishCommand()
  return script(text.length)
}

type ShellContext = { readonly exported: Readonly<Record<string, string>>; readonly directory: string | null }

const FRESH_SHELL: ShellContext = { exported: {}, directory: null }

type Launch = { readonly assignments: Readonly<Record<string, string>>; readonly words: readonly string[] }

const assignmentsOf = (words: readonly string[]): Record<string, string> =>
  Object.fromEntries(
    words.flatMap(word => {
      const [, name, value] = ASSIGNMENT.exec(word) ?? []
      return name === undefined ? [] : [[name, value!]]
    }),
  )

function asCommand(words: readonly Word[], takesAssignments: boolean): Launch {
  const firstWord = takesAssignments ? words.findIndex(word => !PREFIX_ASSIGNMENT.test(word.raw)) : 0
  const split = firstWord === -1 ? words.length : firstWord
  const assignments = Object.fromEntries(
    words.slice(0, split).map(word => {
      const [prefix, name] = PREFIX_ASSIGNMENT.exec(word.raw)!
      return [name!, word.value.slice(prefix.length)]
    }),
  )
  const program = words[split]?.value
  if (program !== 'env' && (program === undefined || !MODIFIERS.has(program))) {
    return { assignments, words: words.slice(split).map(word => word.value) }
  }
  const launched = asCommand(words.slice(split + 1), program === 'env')
  return { assignments: { ...assignments, ...launched.assignments }, words: launched.words }
}

function normalized(path: string): string {
  const segments = path.split('/').reduce<readonly string[]>((kept, segment) => {
    if (segment === '' || segment === '.') return kept
    if (segment === '..') return kept.slice(0, -1)
    return [...kept, segment]
  }, [])
  return `${path.startsWith('/') ? '/' : ''}${segments.join('/')}`
}

function directoryAfter(directory: string | null, target: string | undefined): string | null {
  if (target === undefined) return null
  if (target.startsWith('/') || target.startsWith('~')) return normalized(target)
  return directory === null ? null : normalized(`${directory}/${target}`)
}

const withoutNames = (exported: Readonly<Record<string, string>>, names: readonly string[]) =>
  Object.fromEntries(Object.entries(exported).filter(([name]) => !names.includes(name)))

function contextAfter(command: Launch, context: ShellContext): ShellContext {
  const [program, ...rest] = command.words
  if (program === 'export') return { ...context, exported: { ...context.exported, ...assignmentsOf(rest) } }
  if (program === 'unset') return { ...context, exported: withoutNames(context.exported, rest) }
  if (program === 'cd') return { ...context, directory: directoryAfter(context.directory, rest[0]) }
  return context
}

function inContext(command: Launch, context: ShellContext): Launch {
  const [program, ...rest] = command.words
  const isRelative = program !== undefined && program.startsWith('./') && context.directory !== null
  return {
    assignments: { ...context.exported, ...command.assignments },
    words: isRelative ? [`${context.directory}/${program.slice(2)}`, ...rest] : command.words,
  }
}

type ScopeContexts = Readonly<Record<string, ShellContext>>

const scopeKey = (scope: Scope) => scope.join(' ')

function contextIn(contexts: ScopeContexts, scope: Scope): ShellContext {
  return contexts[scopeKey(scope)] ?? (scope.length === 0 ? FRESH_SHELL : contextIn(contexts, scope.slice(0, -1)))
}

export function simpleCommands(text: string): readonly SimpleCommand[] | null {
  const script = parseScript(text, 0, null, [])
  if (script === null) return null
  const { records } = script
  return records.reduce(
    (shell, record, at) => {
      const command = asCommand(record.words, true)
      const context = contextIn(shell.contexts, record.scope)
      const decidesStatus =
        !record.isQuiet && records.slice(at + 1).every(later => later.isNested || later.follows === '&&')
      return {
        contexts: record.isPiped
          ? shell.contexts
          : { ...shell.contexts, [scopeKey(record.scope)]: contextAfter(command, context) },
        commands: [...shell.commands, { ...inContext(command, context), decidesStatus }],
      }
    },
    { contexts: {} as ScopeContexts, commands: [] as readonly SimpleCommand[] },
  ).commands
}

const baseName = (path: string) => path.slice(path.lastIndexOf('/') + 1)

export function programOf(command: SimpleCommand): readonly string[] {
  const [first, ...rest] = command.words
  if (first === undefined) return []
  return SHELLS.has(baseName(first)) && rest[0] !== undefined && !rest[0].startsWith('-') ? rest : command.words
}

export const isPipelineClean = (command: SimpleCommand) => {
  const [program, verb] = programOf(command)
  return program !== undefined && baseName(program) === 'pipeline' && verb === 'clean'
}

export const isRunScript = (command: SimpleCommand) => {
  const [program] = programOf(command)
  return program !== undefined && normalized(program).includes('/.mitosis/') && baseName(program) === 'run.zsh'
}

export const isShipping = (command: SimpleCommand) => (command.assignments.SHIP ?? '') !== ''

